 5	public final class NaivePatternSearch {
 6	
 7	    private NaivePatternSearch() {
 8	    }
 9	
10	    public static List<Integer> search(String pattern, String text) {
11	        Objects.requireNonNull(pattern, "pattern must not be null");
12	        Objects.requireNonNull(text, "text must not be null");
13	
14	        int patternLength = pattern.length();
15	        int textLength = text.length();
16	
17	        if (patternLength > textLength) {
18	            return List.of();
19	        }
20	
21	        List<Integer> matchIndexes = new ArrayList<>();
22	
23	        for (int startIndex = 0; startIndex <= textLength - patternLength; startIndex++) {
24	            if (matchesAt(pattern, text, startIndex, patternLength)) {
25	                matchIndexes.add(startIndex);
26	            }
27	        }
28	
29	        return matchIndexes;
30	    }
31	
32	    public static String joinMatchIndexes(List<Integer> matches) {
33	        Objects.requireNonNull(matches, "matches must not be null");
34	
35	        if (matches.isEmpty()) {
36	            return "";
37	        }
38	
39	        StringBuilder formattedMatches = new StringBuilder();
40	        for (int index = 0; index < matches.size(); index++) {
41	            if (index > 0) {
42	                formattedMatches.append(' ');
43	            }
44	            formattedMatches.append(matches.get(index));
45	        }
46	
47	        return formattedMatches.toString();
48	    }
49	
50	    private static boolean matchesAt(
51	            String pattern, String text, int startIndex, int patternLength) {
52	        for (int offset = 0; offset < patternLength; offset++) {
53	            if (text.charAt(startIndex + offset) != pattern.charAt(offset)) {
54	                return false;
55	            }
56	        }
57	
58	        return true;
59	    }
60	}

