 3	public final class NaivePatternSearchTest {
 4	
 5	    private NaivePatternSearchTest() {
 6	    }
 7	
 8	    public static void main(String[] args) {
 9	        assertMatches("finds repeated pattern matches",
10	                "aaba", "aabaacaadaabaaba", List.of(0, 9, 12));
11	        assertMatches("returns no matches when pattern is absent",
12	                "xyz", "aabaacaadaabaaba", List.of());
13	        assertMatches("returns no matches when pattern is longer than text",
14	                "longpattern", "short", List.of());
15	        assertMatches("supports empty patterns consistently",
16	                "", "abc", List.of(0, 1, 2, 3));
17	        assertEquals("joins match indexes for CLI output",
18	                "0 9 12", NaivePatternSearch.joinMatchIndexes(List.of(0, 9, 12)));
19	        assertSearchInput("uses CLI defaults when no arguments are provided",
20	                new String[0], "aabaacaadaabaaba", "aaba");
21	        assertSearchInput("allows overriding the text only",
22	                new String[] {"banana"}, "banana", "aaba");
23	        assertSearchInput("allows overriding both text and pattern",
24	                new String[] {"banana", "ana"}, "banana", "ana");
25	    }
26	
27	    private static void assertMatches(
28	            String scenario, String pattern, String text, List<Integer> expectedMatches) {
29	        assertEquals(scenario, expectedMatches, NaivePatternSearch.search(pattern, text));
30	    }
31	
32	    private static void assertSearchInput(
33	            String scenario, String[] args, String expectedText, String expectedPattern) {
34	        NaivePatternSearchCli.SearchInput input = NaivePatternSearchCli.parseArguments(args);
35	        assertEquals(scenario + " (text)", expectedText, input.text());
36	        assertEquals(scenario + " (pattern)", expectedPattern, input.pattern());
37	    }
38	
39	    private static void assertEquals(String scenario, Object expected, Object actual) {
40	        if (!expected.equals(actual)) {
41	            throw new AssertionError(
42	                    scenario + ": expected " + expected + " but was " + actual);
43	        }
44	    }
45	}

